package com.tarapickle.identity.domain.model;
import jakarta.persistence.*; import lombok.*; import java.time.*; import java.util.*;
@MappedSuperclass @Getter public abstract class OneTimeToken { @Id protected UUID id; @Column(name="user_id",nullable=false) protected UUID userId; @Column(name="token_hash",nullable=false,length=64) protected String tokenHash; @Column(name="expires_at",nullable=false) protected Instant expiresAt; @Column(name="used_at") protected Instant usedAt; @Column(name="created_at",nullable=false) protected Instant createdAt; @Version protected long version; protected OneTimeToken(){} protected OneTimeToken(UUID uid,String hash,Instant now,Instant expires){id=UUID.randomUUID();userId=uid;tokenHash=hash;createdAt=now;expiresAt=expires;} public boolean valid(Instant now){return usedAt==null&&expiresAt.isAfter(now);} public void use(Instant now){if(!valid(now))throw new IllegalStateException("Token is expired or already used");usedAt=now;} }
